fields.InputDefinition:
{
  "goal": "Open the Chat application and wait for the workspace. Do NOT plain-click any conversation (that opens it and ends a selection). In the left sidebar, find the conversations 'Quarterly report draft' and 'Event sponsorship ideas' (if either is missing, use any two conversations). Hold Ctrl while clicking the first row (a Click with \"Modifiers\": [\"ControlOrMeta\"]), then Ctrl-click the second row the same way. Confirm both rows are tinted as selected and the search box at the top of the list is replaced by a selection bar that reads '2 selected' with small icon buttons: an X (Clear selection), a thumbtack (Pin), a folder tree (Move to folder), a person-plus (Share) and a trash can (Delete). If Ctrl-click does not select, hover each row and click the small checkbox at its left edge instead. Then right-click one of the two selected rows (a Click with \"Button\": \"right\") and confirm one context menu opens with a '2 selected' header and the items Pin, Unpin, Move to folder, 'Share 2 conversations' and 'Delete 2'. Do NOT click any menu item. Press Escape to close the menu, then click the X (Clear selection) at the left end of the selection bar and confirm the tint goes away and the 'Search conversations...' box returns. Seeing the selection bar and the multi-row right-click menu is success — do NOT pin, move, share or delete anything. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
